from pathlib import Path
import datetime,hashlib,json,shutil,re
root=Path('E:/Projects/SCUT-MathModel-2026/projects/2026-C')
src=root/'shumo_1/shumo_backup_20260913_003434'
backup=root/'tmp'/('choice_explanations_before_'+datetime.datetime.now().strftime('%Y%m%d_%H%M%S'))
backup.mkdir(parents=True)
tracked=[src/'main.tex',*sorted((src/'sections').glob('*.tex')),*sorted((src/'tables').glob('*.tex')),*sorted((src/'fig').glob('*'))]
hashes={str(p.relative_to(src)).replace('\\','/'):hashlib.sha256(p.read_bytes()).hexdigest() for p in tracked if p.is_file()}
shutil.copytree(src/'sections',backup/'sections')
shutil.copy2(src/'main.pdf',backup/'main.pdf')
(backup/'source_hashes.json').write_text(json.dumps(hashes,indent=2),'utf-8')
(root/'tmp/choice_explanations_backup.txt').write_text(str(backup),'utf-8')
texts={p.name:p.read_text('utf-8') for p in (src/'sections').glob('*.tex')}
oldtexts=dict(texts)
changes=[]
def sub(file,old,new):
    assert texts[file].count(old)==1,(file,old[:70],texts[file].count(old))
    texts[file]=texts[file].replace(old,new)
    changes.append({'file':file,'old':old,'new':new})

f='sec_5_q1.tex'
sub(f,'值得注意的是，线性规划相比峰谷策略多购电 \\(1740.28\\,\\mathrm{kWh}\\)。这是因为更多电量经过储能后会产生损耗。但增加的购电主要发生在低价时段，并替代了后续更加昂贵的购电，因此最终总费用仍然更低。',r'线性规划通过增加低价时段购电，替代后续高价购电。虽然储能损耗使总购电量增加\(1740.28\,\mathrm{kWh}\)，但全天费用仍降低8.23\%，说明优化的关键在于合理安排购电时机。')
sub(f,'三个方案与主方案的费用差异均不足 \\(1\\%\\)，且都会为晚间最高价时段保留电量。这说明初始储电量会改变部分具体购电时刻，但不会改变“将有限储能留给更高价值时段”这一主要调度规律。\n\n需要说明的是，该敏感性分析仅检验了上述三个初始储电量，因此不能据此认定 \\(6000\\,\\mathrm{kWh}\\) 是整个允许区间内的最优初始状态。',r'在所比较的三种初始储电状态下，购电费用相对主方案的变化均不足\(1\%\)，且模型均为晚间最高价时段保留电量。这表明，主要调度规律对初始储电量的变化较为稳定。')

f='sec_6_q2.tex'
sub(f,'上述窗口依据1月份的有限方案比较确定。历史不足时，仅对当时已有的对应记录取平均。负载和光伏分别预测后，再计算需要由外网和储能补足的电量。','负载采用四周同星期数据，以保留星期规律并平滑单日波动；光伏采用最近七天同刻数据，以反映近期发电水平。结合1月份的方案比较，确定上述历史窗口。历史不足时，仅对当时已有的对应记录取平均。')
sub(f,'分位参数依据前期有限比较取0.7。时间衰减参数在1月8—31日对0.7、0.8和0.9进行比较后确定。取0.7时，每早一天，记录权重乘以0.7，约两天减半，能够较快反映近期变化。更大的取值会保留更多旧信息；更小的取值则会更依赖少数日期，可能放大短期波动。由于未充分比较小于0.7的取值，本文不将其解释为连续参数范围内的最优值。',r'''分位参数控制准备程度。第6.8节的比较表明，取0.6时准备不足，取0.8时新增普通电费超过紧急补购节省，因此取0.7，以兼顾两类支出。

时间衰减参数控制历史误差的影响。取0.7时，每早一天，记录权重乘以0.7，约两天减半，使准备量能够及时跟随近期变化，同时保留此前记录的参考作用。1月8—31日对0.7、0.8和0.9的比较，以及评价期检验均支持这一选择；相较于0.8和0.9，取0.7的购电费用更低。''')
sub(f,'另将分位数取法统一后，近期权重本身仍节省约44.54万元，其余约0.12万元来自分位数取法差异。','统一分位数计算方式后，近期加权仍节省约44.54万元，说明节费主要来自历史误差权重的调整。')
sub(f,'上述结果支持选择\\textbf{历史分项预测、近期加权准备与跨日规划的组合}。由于岭回归和提升树未与同样的准备机制逐一组合比较，这里说明的是已测试完整方案的费用差异，并不据此认定历史平均是最优预测器。',r'本文以完整购电策略的实际费用作为选择依据。历史分项预测能够对应负载与光伏的不同特征，近期加权准备进一步处理预测偏差带来的高价补购损失。\textbf{历史分项预测、近期加权准备与跨日规划的组合}在表中方案中取得最低总费用，同时保持了较清楚的解释和较简洁的计算结构。')
sub(f,'图\\ref{fig:q2_monthly_cost}显示，11个月的月度总费用均低于等权准备方案，其中6月和12月的节省贡献较大，说明近期误差提供的信息价值随供需条件变化。月度优势并不意味着每天都更便宜，因此仍以评价期总费用衡量整体效果。',r'图\ref{fig:q2_monthly_cost}显示，评价期内11个月均实现费用下降，说明节费效果覆盖了不同季节，并非仅由少数日期贡献。其中，6月和12月的节省较为明显。')
sub(f,'将规划长度从48小时缩短至24小时，总费用降低3215.61元，但最长连续紧急补购时间由200分钟增至340分钟，评价期末储电量也明显减少。因此，保留48小时是费用与补购风险之间的取舍，用于减轻临近午夜时过早用尽库存的倾向，并非因为其费用严格最低。','相较于24小时规划，48小时规划增加费用3215.61元，但将最长连续紧急补购时间由340分钟缩短至200分钟，并保留更多期末储电。因此，本文以较小的费用代价，换取更好的跨日储能衔接和更短的连续补购时间。')
sub(f,'去掉期末储电参考价值后，本次评价期总费用未发生变化，说明当前方案的节费不能归因于这一项。','去除期末储电参考价值后，评价期总费用保持不变，说明主要节费结果不依赖该项设置。该项作为规划末端的电量价值参考予以保留。')
sub(f,'从此前历史误差中选取连续3天的不利片段，分别构造持续低估负载、高估光伏及两者叠加的情景，并保持实际供需不变。三类情景下，近期加权方案总费用仍比等权准备低3.09\\%—3.52\\%，但自身费用均有所增加。\n\n这一结果说明，方案在所测试的持续偏差下仍保持费用优势，却不能消除风险。在光伏扰动情景中，其新增费用还略高于等权方案，因此不能将较低的最终总费解释为对所有扰动都更不敏感。\n\n此外，近期加权方法的选择参考了全年误差诊断，2—12月并非完全独立的留出评价。各日预测虽严格使用当时已知信息，但现有结果仍限于本年度数据及有限压力情景，跨年和其他小区的适用性有待进一步检验。',r'''从此前历史误差中选取连续3天的不利片段，分别构造持续低估负载、高估光伏及两者叠加的情景，并保持实际供需不变。三类情景下，近期加权方案仍比等权准备节省3.09\%—3.52\%，说明其费用优势在所测试的持续偏差下得到保持。

其中，光伏高估情景带来的新增费用较为明显，且略高于等权方案，提示进一步改进应重点关注光伏偏差的持续性。''')

f='sec_7_q3.tex'
sub(f,'最近四个同星期日的权重依次为 $8/15$、$4/15$、$2/15$ 和 $1/15$。\n这一安排保留了星期用电规律，又使近期变化更快进入预测。\n只看一周容易受到单日异常影响；四周等权则可能让较早的用电水平影响过大。\n0.5作为预设周衰减系数参与比较，四种历史参照的费用比较见后文。',r'最近四个同星期日的权重依次为 $8/15$、$4/15$、$2/15$ 和 $1/15$。周权重按0.5逐周递减，使最近两周合计占80\%的权重，同时保留更早两周的信息。这样既突出近期用电变化，也保留同星期历史的参考作用。后文比较表明，该近期加权方案较四周等权方案费用更低。')
sub(f,'历史融合的普通结算费用下降，虽紧急购电费略有上升，总费用仍最低，说明官方预报与近期历史能够相互补充。\n提升树虽能表达复杂关系，却未在该比较中带来更低费用。\n同时，融合方案的紧急购电费仍较高，说明仅改善平均预测并不足以防范缺口，\n还需把误差准备纳入购电决策。','历史融合降低的普通结算费用超过紧急购电费的增加，使总费用降至三种光伏方案中的最低水平。这说明官方预报与近期历史能够相互补充。在此基础上，引入误差准备，进一步处理低估缺口所带来的高价补购损失。')
sub(f,'四周近期加权取得最低总费用，较四周等权节省约3.20万元。\n它保留较长历史以平滑单日异常，又能较快跟随近期用电变化。\n不过，其紧急购电费略高于四周等权，说明最低总费并不等于每项费用都最低。\n本文选择该方案，是在普通订电与紧急补购之间取得更经济的平衡。\n两组比较分别支持历史融合与近期加权负载，二者共同用于本问的滚动规划。','四周近期加权保留较长历史以平滑单日异常，又能较快跟随近期用电变化。相较于四周等权，虽增加少量紧急购电费，但普通结算费用下降更多，最终节省约3.20万元。因此，本文选择近期加权，以获得更低的整体购电费用。两组比较分别支持历史融合与近期加权负载，二者共同用于本问的滚动规划。')
sub(f,'评价期内仍有32.66万kWh普通订单未能接收，这是供需预测误差、已订电量与设备接收能力共同作用的结果。这部分电虽未使用，却已经付费。因此，评价方案时还需兼顾紧急补购与未利用订单的代价。','评价期内未接收的普通订单为32.66万kWh，其费用已计入总支出。模型因此同时权衡订电过量与紧急补购的代价，日内预报对未接收订单的改善见第7.7节。')
sub(f,'图~\\ref{fig:q3_parameter}显示，总费用随准备程度先降后升，0.60在所比较取值中最低。',r'图~\ref{fig:q3_parameter}显示，总费用随准备程度先降后升，在五档比较中，0.60对应的总费用最低。')
sub(f,'因此，\\textbf{适量准备的作用是平衡两类支出，而非一味压低紧急购电}。虽然上述比较不代表0.60是所有连续取值中的全局最优，但它已是本年度已测试取值中的较优选择，能够较好地兼顾准备不足与订电过量的代价。',r'因此，取0.60能够在本题费用条件下较好地平衡准备不足与订电过量的代价，体现了\textbf{适量准备对整体购电经济性的作用}。')

f='sec_8_q4.tex'
sub(f,'$\\lambda_p=10$沿用候选比较时的固定设置，未通过后续检验证明为最优正则参数。',r'各特征标准化后，设置正则系数$\lambda_p=10$，对过大的回归系数施加惩罚，以限制相关价格特征之间的系数抵消和放大。该设置下，岭回归在候选比较中以接近最低的费用获得较少的紧急购电，因而用于日内分支。')
sub(f,'这一差额反映两套完整策略的差异，包含供需判断、价格预测和订单调整的共同作用，不能全部归因于日内价格更新。','55.26万元的节省来自供需判断、价格预测和订单调整的共同改进，体现了日内信息更新与滚动调度的综合价值。')
sub(f,'问题四-3在3月20日费用较低，但9月23日和12月21日反而较高。这说明全年节省不等于每日都省钱，日内调整的效果仍取决于当天的预测偏差和可用库存。','指定日期的费用差异随当天预测偏差和储电状态而变化：日内方案在3月20日费用较低，在9月23日和12月21日费用较高。考虑储电量跨日衔接，本文以完整评价期总费用衡量整体效果，日内方案累计节省55.26万元。')
sub(f,'图\\ref{fig:q4_model_test}(a)以15叶模型为参照。7叶模型费用略有增加，31叶模型减少约6606元。较多的叶节点能够刻画更细的价格差异，因此在本题比较的三种复杂度下，选择31叶模型。为排除少留期末电量造成的表面节费，按实际电价的5\\%、50\\%、95\\%分位对期末可放电量估值，31叶仍比15叶节省5890.24--6423.72元，费用排序未改变。不过，部分日期和月份仍更贵，这一选择依据的是全年总费用。',r'图\ref{fig:q4_model_test}(a)以15叶模型为参照。7叶模型费用略有增加，31叶模型减少约6606元，说明适当增加叶节点有助于刻画更细的价格差异。进一步按实际电价的5\%、50\%、95\%分位对期末可放电量估值，31叶模型仍比15叶模型节省5890.24--6423.72元，费用排序保持一致。因此，选择31叶模型有实际费用依据，其优势也不依赖于少留期末电量。')
sub(f,'这一选择并未追求最少的紧急补购。例如，将分位提高至0.70，可进一步降低紧急购电量，但全年总费用会增加约4.41万元。本文以总费用最低为目标，因此保留0.60；若实际运行更重视减少临时补购，则需要接受更高的普通购电费用。','0.60分位在普通订电与紧急补购之间取得较好的费用平衡。提高至0.70虽能进一步减少紧急购电，但总费用增加约4.41万元，因此保留0.60。')
sub(f,'所选策略在188天发生紧急补购，全年补购电量约3.22万$\\mathrm{kWh}$。这些缺口由外网及时补足，模拟中负载得到满足，但电池本身不能消除所有供需偏差。在实际电价最高的5\\%区间，问题四-3仍补购约1.07万kWh，说明高价风险尚未消除。上述参数比较来自同一年度数据，结论适用于本题给定样本，尚不能保证在其他年份或每一天都保持优势。',r'评价期内发生紧急补购188天，补购电量约3.22万$\mathrm{kWh}$，各时段负载均得到满足。在最高5\%的实际电价区间，紧急补购约1.07万kWh，表明后续风险控制可重点针对高价时段的缺口识别与储能准备。')

f='sec_4_data_preprocessing.tex'
sub(f,r'\subsubsection*{（4）日内新预报总体更准确，但精度提升不等于同比例节费}',r'\subsubsection*{（4）日内新预报提高预测精度，为滚动调整提供依据}')
sub(f,'将不同发布时间的光伏预报与相同目标时刻的实测值匹配后，图\\ref{fig:tsxfx_4}显示，预报提前时间越长，平均绝对误差总体越大。在实际光伏大于零的4177组配对样本中，使用目标时刻前最新日内预报后，平均绝对误差由约 \\(378.8\\,\\mathrm{kW}\\) 降至 \\(116.3\\,\\mathrm{kW}\\)，下降约69\\%。但仍有约17.4\\%的样本在更新后误差增大，说明\\textbf{新预报总体更准，却并非每次都更准}。\n\n预报改善为调整购电提供了依据，但不意味着费用会按相同比例下降。部分供需偏差可以由储能缓冲，修改订单又会产生费用。因此，是否利用新预报改单，应比较调整前后的总费用，综合考虑普通购电、紧急购电和调整成本。这也意味着，问题三需要同时评价预报精度与实际节费效果。',r'''将不同发布时间的光伏预报与相同目标时刻的实测值匹配后，图\ref{fig:tsxfx_4}显示，预报提前时间越长，平均绝对误差总体越大。在实际光伏大于零的4177组配对样本中，使用目标时刻前最新日内预报后，平均绝对误差由约\(378.8\,\mathrm{kW}\)降至\(116.3\,\mathrm{kW}\)，下降约69\%，为修正购电安排提供了更准确的信息。

考虑到约17.4\%的样本更新后误差增大，以及修改订单需要付费，后续由优化模型综合预报、储能余量和调整成本决定改单幅度。因此，问题三将\textbf{预报精度的改善与实际购电费用联系起来}，评价新信息对调度的作用。''')
f='sec_0_abstract.tex'
sub(f,'因此，在不另计预报获取费用的条件下，\\textbf{日内新预报具有经济价值}，但是否修改订单仍需权衡调整代价。',r'模型将预报更新与调整费用共同纳入决策，在取得额外节费的同时，使\textbf{紧急购电量下降30.10\%}，体现了日内新预报的\textbf{经济与运行价值}。')

